import{_ as o,c as r,o as s,ah as n}from"./chunks/framework.RCw5T9E9.js";const u=JSON.parse('{"title":"Избранное","description":"","frontmatter":{"title":"Избранное"},"headers":[],"relativePath":"ru/props/favorite.md","filePath":"ru/props/favorite.md"}'),e={name:"ru/props/favorite.md"};function a(i,t,l,g,p,d){return s(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="избранное-props" tabindex="-1">Избранное (Props) <a class="header-anchor" href="#избранное-props" aria-label="Permalink to &quot;Избранное (Props)&quot;">​</a></h1><p><strong>Избранное</strong> в разделе <strong>Props</strong> — это сохраняемый список <strong>компонентов</strong>, к которым можно быстро возвращаться между сессиями работы с инспектором. Отмеченные строки поднимаются <strong>в начало</strong> таблицы, рядом с именем отображается <strong>звезда</strong>, а в шапке доступен счётчик найденных избранных на текущем экране.</p><p>Общее описание вкладки Props: <a href="/qa-tools/docs/ru/props/general.html">Основные возможности</a>.</p><p><strong>Избранное для Pinia</strong> — отдельный список на вкладке <strong>Stores</strong> и в настройках <strong>Options → Pinia Store</strong>; здесь описаны только <strong>компоненты Vue</strong>.</p><hr><h2 id="где-добавить-и-убрать" tabindex="-1">Где добавить и убрать <a class="header-anchor" href="#где-добавить-и-убрать" aria-label="Permalink to &quot;Где добавить и убрать&quot;">​</a></h2><p>Добавить компонент в избранное можно несколькими способами.</p><ul><li><strong>В карточке компонента</strong> (детальный просмотр) — в заголовке доступна кнопка <strong>звезды</strong>, которая включает или снимает признак избранного для текущего компонента.</li><li><strong>Через контекстное меню строки в таблице Props</strong> — команда добавления или удаления из избранного доступна среди действий над выбранным компонентом.</li><li><strong>В таблице Props</strong> — быстрый клик по области <strong>звезды</strong> у строки также переключает избранное, даже если иконка ещё не отображается постоянно.</li><li><strong>В Options</strong> — секция <strong>Favorite Components</strong> в блоке <strong>Props</strong>. Список и карточка деталей описаны ниже. Кнопки <strong>Add</strong> нет: записи появляются со вкладки Props.</li></ul><p>После изменения списка таблица Props <strong>пересортировывается</strong>: отмеченные компоненты перемещаются выше остальных (если это не противоречит текущим фильтрам поиска).</p><h3 id="favorite-components-в-options" tabindex="-1">Favorite Components в Options <a class="header-anchor" href="#favorite-components-в-options" aria-label="Permalink to &quot;Favorite Components в Options&quot;">​</a></h3><p>Блок последний на <strong>Options → Props</strong>. Кнопки <strong>Add</strong> нет. Строки остаются в порядке сохранения.</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Что показывает</th></tr></thead><tbody><tr><td><strong>Component</strong></td><td>Имя, а под ним тег, точка и сохранённая строка классов. Пробелы в строке классов остаются пробелами.</td></tr><tr><td><strong>Added</strong></td><td>Только локальная дата.</td></tr></tbody></table><p>Меню строки — только <strong>Delete</strong>. <strong>Delete</strong> удаляет все сохранённые записи с этим id. Пустая таблица: <em>No favorite components</em>.</p><p>Клик открывает <strong>Favorite Details</strong>: <strong>Component Name</strong>, <strong>Element</strong> (тег, точка и строка классов) и <strong>Added</strong> — локальные дата и время. Кнопки <strong>Edit</strong> нет. <strong>Назад</strong> или <strong>Escape</strong> закрывают карточку. Если ничего не выбрано, панель пишет <em>Select an item to see details</em>. Если запись удалили при открытой карточке, она пишет <em>Item no longer exists</em>. Ниже <strong>1000</strong> px карточка закрывает список настроек, пока её не закроют.</p><p>Карточка не выбирает этот компонент на вкладке Props.</p><hr><h2 id="что-именно-сохраняется" tabindex="-1">Что именно сохраняется <a class="header-anchor" href="#что-именно-сохраняется" aria-label="Permalink to &quot;Что именно сохраняется&quot;">​</a></h2><p>Для каждой записи хранится, среди прочего:</p><ul><li><strong>имя компонента</strong>;</li><li><strong>идентификатор</strong> для сопоставления со строкой в дереве (в том числе форма с привязкой к корневому DOM-элементу: тег и классы);</li><li>при необходимости <strong>внутренний идентификатор узла</strong> текущей сессии (<strong>nodeId</strong>) — чтобы различать экземпляры с одинаковым именем и похожей разметкой;</li><li><strong>время добавления</strong> (для отображения в списке настроек).</li></ul><p>Это позволяет списку сохраняться после <strong>перезагрузки страницы</strong>: при следующем построении дерева инспектор повторно ищет компонент по сохранённым признакам.</p><hr><h2 id="как-выполняется-сопоставление" tabindex="-1">Как выполняется сопоставление <a class="header-anchor" href="#как-выполняется-сопоставление" aria-label="Permalink to &quot;Как выполняется сопоставление&quot;">​</a></h2><p>При открытии дерева и обновлении состояния избранного используется <strong>устойчивое сравнение идентификаторов</strong>.</p><ul><li>Если сохранён идентификатор в форме <strong>числового uid текущей сессии</strong>, совпадение возможно <strong>только в пределах текущего жизненного цикла дерева</strong> (после полного пересоздания uid изменится).</li><li>Для записей с <strong>именем компонента и сигнатурой корневого элемента</strong> (тег, классы и т.д.) сопоставление опирается на эти <strong>стабильные признаки</strong>, а не на внутренний путь в дереве Vue.</li></ul><p>Для старых записей, где сохранён только <strong>uid сессии</strong>, инспектор дополнительно может использовать <strong>метаданные компонента</strong> (имя, тег, класс), чтобы восстановить соответствие после перезагрузки.</p><p>Если на странице появляется <strong>несколько похожих кандидатов</strong>, сопоставление может выбрать другой экземпляр; в таком случае рекомендуется снять признак избранного и добавить компонент заново уже с актуального узла.</p><hr><h2 id="счетчик-в-шапке" tabindex="-1">Счётчик в шапке <a class="header-anchor" href="#счетчик-в-шапке" aria-label="Permalink to &quot;Счётчик в шапке&quot;">​</a></h2><p>Бейдж виден всегда. Если ничего не сохранено, на нём <code>0</code>, иначе видимые избранные / всего сохранённых. Жёлтый, когда хотя бы одна видимая строка в избранном.</p><p>Клик по бейджу открывает <strong>Options → Props → Favorite Components</strong>.</p><hr><h2 id="практические-советы" tabindex="-1">Практические советы <a class="header-anchor" href="#практические-советы" aria-label="Permalink to &quot;Практические советы&quot;">​</a></h2><ul><li>Используйте избранное для <strong>опорных компонентов</strong>: шапки приложения, часто проверяемых виджетов, проблемных зон интерфейса.</li><li>После <strong>изменений в структуре DOM</strong> полезно проверить, что избранное всё ещё связано с нужным экземпляром.</li><li>Избранное <strong>не влияет</strong> на выполнение приложения и не связано с <strong>чёрным списком</strong> компонентов — это независимые механизмы.</li></ul><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/ru/props/general.html">Основные возможности Props</a></li><li><a href="/qa-tools/docs/ru/props/blacklist.html">Чёрный список</a></li><li><a href="/qa-tools/docs/ru/options/customize.html">Персонализация / настройки</a></li><li><a href="/qa-tools/docs/ru/store/general.html">Основные возможности Store (Pinia)</a> — избранное для store настраивается отдельно</li></ul>',36)])])}const c=o(e,[["render",a]]);export{u as __pageData,c as default};
